<script setup lang="ts">
import {planSchema,presets,type Plan,type Settings} from '#shared/model'
import {dailySession,weekday} from '#domain/learning'
import {weaknessRecommendations,type WeakType} from '#domain/learning'
const {state,ready,savePlan,busy}=useLearning(),draft=ref<Plan>(JSON.parse(JSON.stringify(state.value.plan))),message=ref(''),failed=ref(false),selectedDay=ref('1'),weekdayCustom=ref<Settings>(JSON.parse(JSON.stringify(draft.value.settings)))
const weakness=computed(()=>weaknessRecommendations(state.value.sessions))
const labels=['일','월','화','수','목','금','토']
watch(ready,loaded=>{if(loaded)draft.value=JSON.parse(JSON.stringify(state.value.plan))})
function toggle(n:number){draft.value.weekdays=draft.value.weekdays.includes(n)?draft.value.weekdays.filter(x=>x!==n):[...draft.value.weekdays,n]}
function addWeekday(){draft.value.weekdaySettings[selectedDay.value]=JSON.parse(JSON.stringify(weekdayCustom.value));message.value=`${labels[Number(selectedDay.value)]}요일 조건을 추가했어요. 아래의 계획 저장을 눌러 주세요.`;failed.value=false}
function focusType(type:WeakType){const [operator,digitsA,digitsB,difficulty,carryBorrowType]=type.key.split('/');if(!operator||!digitsA||!digitsB||!difficulty)return;draft.value.settings={...draft.value.settings,operators:[operator as Settings['operators'][number]],digitsA:Number(digitsA),digitsB:Number(digitsB),difficulty:difficulty as Settings['difficulty'],carry:operator==='divide'?'any':carryBorrowType==='required'?'required':'none'}}
async function save(){message.value='';failed.value=false;try{const parsed=planSchema.safeParse(draft.value);if(!parsed.success)throw new Error('날짜, 문제 수, 연산 조건을 확인해 주세요.');const {foundation:_foundation,ratios:_ratios,...flatPlan}=parsed.data;const p={...flatPlan,updatedAt:new Date().toISOString()};for(const day of p.weekdays){const d=new Date(`${p.startDate}T12:00:00+09:00`);d.setUTCDate(d.getUTCDate()+(day-weekday(p.startDate)+7)%7);dailySession(p,new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul'}).format(d))}await savePlan(p);message.value='학습 계획을 저장했어요. 다음 새 과제부터 적용돼요. 이미 시작한 학습은 이어서 풀 수 있도록 그대로 유지돼요.'}catch(e){failed.value=true;message.value=(e as Error).message}}
</script>
<template><div class="page narrow-page"><div class="eyebrow">A LITTLE, EVERY DAY</div><h1>나의 학습 계획</h1><p class="page-intro">하루 분량과 연산 조건을 정하면 바로 시작할 수 있어요.</p><p v-if="!ready" class="muted" role="status">저장한 계획을 불러오고 있어요…</p><form v-else class="form-surface" @submit.prevent="save"><fieldset><legend>시작 수준</legend><div class="segmented"><button v-for="(label,key) in {basic:'기초',normal:'보통',advanced:'심화'}" :key="key" type="button" @click="draft.settings=JSON.parse(JSON.stringify(presets[key]))">{{label}}</button></div><p class="muted footnote">프리셋은 시작 조건이에요. 선택 후 원하는 대로 바꿀 수 있어요.</p></fieldset><div class="form-grid"><label>시작일<input v-model="draft.startDate" type="date" required></label><div><label>학습 요일</label><div class="weekday-options"><button v-for="(day,n) in labels" :key="n" type="button" :aria-pressed="draft.weekdays.includes(n)" :class="{active:draft.weekdays.includes(n)}" @click="toggle(n)">{{day}}</button></div></div></div><section class="recommendation-panel"><h2>현재 기록에서 더 연습하면 좋은 유형</h2><p>최근 완료한 최대 5개 세션의 첫 답안을 살펴봐요. 유형별 첫 답안이 3개 미만이면 추천하지 않아요.</p><span v-if="weakness.sessions" class="recommendation-sample">관찰 세션 {{weakness.sessions}}개</span><p v-if="!weakness.types.length" class="muted footnote">아직 추천할 만큼의 기록이 없어요. 기본 계획으로 연습을 이어가세요.</p><button v-for="type in weakness.types" :key="type.key" type="button" class="recommendation-item" @click="focusType(type)"><span>{{type.label}} · 첫 정답률 {{type.rate}}% ({{type.correct}}/{{type.total}})</span><b>이 유형으로 집중 설정</b></button></section><h2 class="form-section-title">오늘 학습 조건</h2><SettingsFields v-model="draft.settings"/><details><summary>요일별 다른 계산 설정</summary><label>요일<select v-model="selectedDay"><option v-for="(day,n) in labels" :key="n" :value="String(n)">{{day}}요일</option></select></label><SettingsFields v-model="weekdayCustom" hide-count/><button type="button" class="btn secondary small" @click="addWeekday">이 요일에 적용</button><div v-for="(_,day) in draft.weekdaySettings" :key="day" class="weekday-override"><span>{{labels[Number(day)]}}요일 · 별도 조건 적용</span><button type="button" class="text-link" @click="delete draft.weekdaySettings[day]">해제</button></div></details><p v-if="message" :class="failed?'alert':'success-message'" role="status">{{message}}</p><div class="form-footer"><span>진행 중인 과제와 지난 기록은 바뀌지 않아요.</span><button class="btn" type="submit" :disabled="busy">계획 저장<AppIcon name="check" :size="18"/></button></div></form></div></template>
